//! kvhttp: an HTTP/1.1 in-memory key-value server.
//!
//! Usage: `kvhttp <port>` (listens on 127.0.0.1).

mod routes;
mod store;

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;
use std::time::Duration;

use hyper::server::conn::http1;
use hyper::service::service_fn;
use hyper_util::rt::{TokioIo, TokioTimer};
use tokio::net::TcpListener;

use crate::store::Store;

/// How long a client may take to send the request head.
const HEADER_TIMEOUT: Duration = Duration::from_secs(30);
/// Back-off after a resource-exhaustion accept failure (e.g. EMFILE).
const ACCEPT_BACKOFF: Duration = Duration::from_millis(10);

fn parse_port(arg: &str) -> Option<u16> {
    arg.parse().ok().filter(|&port| port != 0)
}

#[tokio::main]
async fn main() -> ExitCode {
    let mut args = std::env::args();
    let program = args.next().unwrap_or_else(|| "kvhttp".into());
    let port = match (args.next().as_deref().and_then(parse_port), args.next()) {
        (Some(port), None) => port,
        _ => {
            eprintln!("usage: {program} <port>");
            return ExitCode::from(2);
        }
    };

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = match TcpListener::bind(addr).await {
        Ok(listener) => listener,
        Err(err) => {
            eprintln!("bind {addr}: {err}");
            return ExitCode::FAILURE;
        }
    };
    serve(listener, Arc::new(Store::new())).await;
    ExitCode::FAILURE
}

/// Accepts connections forever, serving each on its own task.
async fn serve(listener: TcpListener, store: Arc<Store>) {
    loop {
        let stream = match listener.accept().await {
            Ok((stream, _)) => stream,
            Err(err) => {
                // Transient failures (aborted handshakes, fd exhaustion) must
                // not take the server down; pause briefly to avoid spinning.
                eprintln!("accept: {err}");
                tokio::time::sleep(ACCEPT_BACKOFF).await;
                continue;
            }
        };
        if let Err(err) = stream.set_nodelay(true) {
            eprintln!("set_nodelay: {err}");
        }
        let store = Arc::clone(&store);
        tokio::spawn(async move {
            let service = service_fn(move |req| routes::handle(Arc::clone(&store), req));
            // Errors here are clients that disconnected or sent garbage;
            // hyper has already answered whatever could be answered.
            let _ = http1::Builder::new()
                .timer(TokioTimer::new())
                // Clients may shut down their write side after sending the
                // request; still answer it.
                .half_close(true)
                .header_read_timeout(HEADER_TIMEOUT)
                .serve_connection(TokioIo::new(stream), service)
                .await;
        });
    }
}

#[cfg(test)]
mod tests {
    use super::parse_port;

    #[test]
    fn ports() {
        assert_eq!(parse_port("8080"), Some(8080));
        assert_eq!(parse_port("65535"), Some(65535));
        assert_eq!(parse_port("0"), None);
        assert_eq!(parse_port("65536"), None);
        assert_eq!(parse_port("-1"), None);
        assert_eq!(parse_port("80x"), None);
        assert_eq!(parse_port(""), None);
    }
}

//! Request routing for the key-value API.

use std::sync::Arc;
use std::time::Duration;

use bytes::Bytes;
use http_body_util::{BodyExt, Full, LengthLimitError, Limited};
use hyper::body::Incoming;
use hyper::header::{CONTENT_TYPE, HeaderValue};
use hyper::{Method, Request, Response, StatusCode};

use crate::store::{PutOutcome, Store};

/// Largest accepted request body (and therefore stored value).
pub const MAX_VALUE: usize = 1024 * 1024;
/// Longest accepted key.
pub const KEY_MAX: usize = 64;
/// How long a client may take to deliver the request body.
const BODY_TIMEOUT: Duration = Duration::from_secs(30);

pub type BoxError = Box<dyn std::error::Error + Send + Sync>;

/// Handles one request. An `Err` means the client went away or stalled, and
/// the connection is dropped without a response.
pub async fn handle(
    store: Arc<Store>,
    req: Request<Incoming>,
) -> Result<Response<Full<Bytes>>, BoxError> {
    let (parts, body) = req.into_parts();
    let collected =
        tokio::time::timeout(BODY_TIMEOUT, Limited::new(body, MAX_VALUE).collect()).await?;
    let body = match collected {
        Ok(collected) => collected.to_bytes(),
        Err(err) if err.is::<LengthLimitError>() => {
            return Ok(empty(StatusCode::PAYLOAD_TOO_LARGE));
        }
        Err(err) => return Err(err),
    };
    Ok(route(&store, &parts.method, parts.uri.path(), body))
}

fn route(store: &Store, method: &Method, path: &str, body: Bytes) -> Response<Full<Bytes>> {
    match path {
        "/health" => match *method {
            Method::GET => with_type(StatusCode::OK, "text/plain", Bytes::from_static(b"ok")),
            _ => empty(StatusCode::METHOD_NOT_ALLOWED),
        },
        "/kv" => match *method {
            Method::GET => with_type(
                StatusCode::OK,
                "application/json",
                list_json(&store.keys()).into(),
            ),
            _ => empty(StatusCode::METHOD_NOT_ALLOWED),
        },
        _ => match path.strip_prefix("/kv/") {
            Some(key) if is_valid_key(key) => handle_key(store, method, key, body),
            Some(_) => empty(StatusCode::BAD_REQUEST),
            None => empty(StatusCode::NOT_FOUND),
        },
    }
}

fn handle_key(store: &Store, method: &Method, key: &str, body: Bytes) -> Response<Full<Bytes>> {
    match *method {
        Method::GET => match store.get(key) {
            Some(value) => with_type(StatusCode::OK, "application/octet-stream", value),
            None => empty(StatusCode::NOT_FOUND),
        },
        Method::PUT => match store.put(key, body) {
            PutOutcome::Created => empty(StatusCode::CREATED),
            PutOutcome::Replaced => empty(StatusCode::OK),
        },
        Method::DELETE if store.delete(key) => empty(StatusCode::NO_CONTENT),
        Method::DELETE => empty(StatusCode::NOT_FOUND),
        _ => empty(StatusCode::METHOD_NOT_ALLOWED),
    }
}

/// A key matches `[A-Za-z0-9_-]{1,64}`.
fn is_valid_key(key: &str) -> bool {
    (1..=KEY_MAX).contains(&key.len())
        && key
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'-')
}

/// Renders keys as a JSON array. Valid keys never need escaping.
fn list_json(keys: &[String]) -> String {
    let mut json = String::with_capacity(2 + keys.iter().map(|k| k.len() + 3).sum::<usize>());
    json.push('[');
    for (i, key) in keys.iter().enumerate() {
        if i > 0 {
            json.push(',');
        }
        json.push('"');
        json.push_str(key);
        json.push('"');
    }
    json.push(']');
    json
}

fn empty(status: StatusCode) -> Response<Full<Bytes>> {
    let mut res = Response::new(Full::default());
    *res.status_mut() = status;
    res
}

fn with_type(status: StatusCode, content_type: &'static str, body: Bytes) -> Response<Full<Bytes>> {
    let mut res = Response::new(Full::new(body));
    *res.status_mut() = status;
    res.headers_mut()
        .insert(CONTENT_TYPE, HeaderValue::from_static(content_type));
    res
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"k".repeat(KEY_MAX)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(KEY_MAX + 1)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("bad.key"));
        assert!(!is_valid_key("%41"));
        assert!(!is_valid_key("é"));
    }

    #[test]
    fn routing_statuses() {
        let store = Store::new();
        let status = |m: Method, p: &str| route(&store, &m, p, Bytes::new()).status();
        assert_eq!(status(Method::GET, "/health"), StatusCode::OK);
        assert_eq!(
            status(Method::POST, "/health"),
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(status(Method::GET, "/nope"), StatusCode::NOT_FOUND);
        assert_eq!(status(Method::GET, "/kv/"), StatusCode::BAD_REQUEST);
        assert_eq!(status(Method::GET, "/kv/a/b"), StatusCode::BAD_REQUEST);
        assert_eq!(
            status(Method::PATCH, "/kv/a"),
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(status(Method::POST, "/kv"), StatusCode::METHOD_NOT_ALLOWED);
        assert_eq!(status(Method::PUT, "/kv/a"), StatusCode::CREATED);
        assert_eq!(status(Method::PUT, "/kv/a"), StatusCode::OK);
        assert_eq!(status(Method::DELETE, "/kv/a"), StatusCode::NO_CONTENT);
        assert_eq!(status(Method::DELETE, "/kv/a"), StatusCode::NOT_FOUND);
    }

    #[test]
    fn json_listing() {
        assert_eq!(list_json(&[]), "[]");
        assert_eq!(list_json(&["a".into(), "b".into()]), r#"["a","b"]"#);
    }
}

//! Thread-safe in-memory key-value store.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock};

use bytes::Bytes;

/// Outcome of [`Store::put`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PutOutcome {
    /// The key did not exist before.
    Created,
    /// An existing value was replaced.
    Replaced,
}

/// Keys are kept ordered so listing needs no extra sort. Values are
/// reference-counted [`Bytes`], so readers clone a handle under the lock and
/// transmit it afterwards; the lock is never held during network I/O.
#[derive(Debug, Default)]
pub struct Store {
    entries: RwLock<BTreeMap<String, Bytes>>,
}

impl Store {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn put(&self, key: &str, value: Bytes) -> PutOutcome {
        let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
        match entries.insert(key.to_owned(), value) {
            None => PutOutcome::Created,
            Some(_) => PutOutcome::Replaced,
        }
    }

    pub fn get(&self, key: &str) -> Option<Bytes> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.get(key).cloned()
    }

    /// Returns `true` if the key existed and was removed.
    pub fn delete(&self, key: &str) -> bool {
        let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
        entries.remove(key).is_some()
    }

    /// Every key, sorted ascending by byte value.
    pub fn keys(&self) -> Vec<String> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.keys().cloned().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn crud() {
        let store = Store::new();
        assert_eq!(
            store.put("a", Bytes::from_static(b"1")),
            PutOutcome::Created
        );
        assert_eq!(
            store.put("a", Bytes::from_static(b"2")),
            PutOutcome::Replaced
        );
        assert_eq!(store.get("a").as_deref(), Some(&b"2"[..]));
        assert!(store.delete("a"));
        assert!(!store.delete("a"));
        assert_eq!(store.get("a"), None);
    }

    #[test]
    fn keys_are_sorted_by_byte_value() {
        let store = Store::new();
        for key in ["b", "_", "B", "a", "-", "0"] {
            store.put(key, Bytes::new());
        }
        assert_eq!(store.keys(), ["-", "0", "B", "_", "a", "b"]);
    }
}
